defmodule TopLevel do

  def decode_element(%{"ADVENTURERCOUNT" => _,"AGENTCOUNT" => _,"ATROXCOUNT" => _,"AVGLVL" => _,"BTCOUNT" => _,"DESCRIPTION" => _,"DOCTORCOUNT" => _,"ENFCOUNT" => _,"ENGINEEERCOUNT" => _,"FEMALECOUNT" => _,"FIXERCOUNT" => _,"GOVERNINGNAME" => _,"HISTORY" => _,"KEEPERCOUNT" => _,"MACOUNT" => _,"MALECOUNT" => _,"MAXLVL" => _,"METACOUNT" => _,"MINLVL" => _,"MONSTERCOUNT" => _,"NAME" => _,"NANOCOUNT" => _,"NANORACECOUNT" => _,"NEUTERCOUNT" => _,"NUMMEMBERS" => _,"OBJECTIVE" => _,"OPIFEXCOUNT" => _,"ORG_DIMENSION" => _,"ORG_INSTANCE" => _,"SHADECOUNT" => _,"SIDE" => _,"SIDE_NAME" => _,"SOLIDERCOUNT" => _,"SOLITUSCOUNT" => _,"TRADERCOUNT" => _,} = value), do: TopLevel2.from_map(value)
  def decode_element(value) when is_binary(value), do: value
  def decode_element(value) when is_list(value), do: value
  def decode_element(_), do: {:error, "Unexpected type when decoding TopLevel.element"}

  def encode_element(%TopLevel2{} = value), do: TopLevel2.to_map(value)
  def encode_element(value) when is_binary(value), do: value
  def encode_element(value) when is_list(value), do: value
  def encode_element(_), do: {:error, "Unexpected type when encoding TopLevel.element"}

  def from_json(json) do
    json
    |> Jason.decode!()
    |> Enum.map(&decode_element/1)
  end

  def to_json(list) do
    Enum.map(list, &encode_element/1)
    |> Jason.encode!()
  end
